package pl.zagranietyper.service;
import org.junit.jupiter.api.Test;import pl.zagranietyper.model.*;import pl.zagranietyper.parser.FootballTeamFirstGoalSyntaxAdapter.Side;import pl.zagranietyper.repository.FootballFixtureEventsRepository;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class FootballTeamFirstGoalSettlementEngineTest {private final FootballTeamFirstGoalSettlementEngine e=new FootballTeamFirstGoalSettlementEngine();private static FootballFixtureEventsSnapshot.Event goal(int i,int m,Integer x,long team,String detail){return new FootballFixtureEventsSnapshot.Event(i,team,"T",1L,"P",null,null,"Goal",detail,m,x,null);}private static FootballFixtureEventsSnapshot.Event var(int i,int m,long team){return new FootballFixtureEventsSnapshot.Event(i,team,"T",1L,"P",null,null,"Var","Goal cancelled",m,null,null);}private static FootballFixtureEventsRepository.FixtureTimeline tl(FootballFixtureEventsSnapshot.Event...events){return new FootballFixtureEventsRepository.FixtureTimeline(1,FootballFixtureEventsSnapshot.FetchStatus.COMPLETE,10L,20L,List.of(events));}
 @Test void settlesHomeAwayOpponentAndPenalty(){assertEquals(SettlementDecision.W,e.settle(Side.HOME,new FootballScore(1,0),tl(goal(0,5,null,10,"Normal Goal"))).decision());assertEquals(SettlementDecision.W,e.settle(Side.AWAY,new FootballScore(0,1),tl(goal(0,5,null,20,"Penalty"))).decision());assertEquals(SettlementDecision.L,e.settle(Side.HOME,new FootballScore(0,1),tl(goal(0,5,null,20,"Normal Goal"))).decision());}
 @Test void ownGoalUsesApiBeneficiaryTeamAndCancelledGoalIsIgnored(){assertEquals(SettlementDecision.W,e.settle(Side.HOME,new FootballScore(1,0),tl(goal(0,5,null,10,"Own Goal"))).decision());assertEquals(SettlementDecision.W,e.settle(Side.AWAY,new FootballScore(0,1),tl(var(0,2,10),goal(1,8,null,20,"Normal Goal"))).decision());}
 @Test void consistencyNoGoalAndChronologyGuards(){assertEquals(SettlementDecision.UNSUPPORTED,e.settle(Side.HOME,new FootballScore(2,0),tl(goal(0,5,null,10,"Normal Goal"))).decision());assertEquals(SettlementDecision.UNSUPPORTED,e.settle(Side.HOME,new FootballScore(0,0),tl()).decision());var same=tl(goal(2,10,null,20,"Normal Goal"),goal(1,10,null,10,"Normal Goal"));assertEquals(SettlementDecision.W,e.settle(Side.HOME,new FootballScore(1,1),same).decision());}
}
